export type BodyFormat = 'markdown' | 'richtext'

export interface EmailTemplate {
  to: string
  cc: string
  bcc: string
  replyTo: string
  subject: string
  /** Which of the two bodies is used. Both are saved so nothing is lost when switching. */
  format: BodyFormat
  /** Markdown body. */
  markdown: string
  /** HTML generated by the rich text editor. */
  body: string
}

/** Fields rendered in each email. */
export type TemplateField = 'to' | 'cc' | 'bcc' | 'replyTo' | 'subject' | 'body'

export const FIELD_LABELS: Record<TemplateField, string> = {
  to: 'To',
  cc: 'Cc',
  bcc: 'Bcc',
  replyTo: 'Reply-To',
  subject: 'Subject',
  body: 'Body',
}

export const EMPTY_TEMPLATE: EmailTemplate = {
  to: '',
  cc: '',
  bcc: '',
  replyTo: '',
  subject: '',
  format: 'markdown',
  markdown: '',
  body: '<p></p>',
}
